import { writeFileSync } from 'node:fs'
import { drillBanks } from '../frontend/src/quick-practice-data.js'

// Strings, numbers, arrays, and objects in this bank are also Python literals.
// Package the bank as a Python module so serverless file tracing includes it.
writeFileSync(new URL('../prep_starter_bank.py', import.meta.url),
  '# Generated by scripts/build-prep-bank.mjs. Edit quick-practice-data.js.\nBANK = ' + JSON.stringify(drillBanks, null, 2) + '\n')
